import collections

def find_cells_on_both_sides_of_2s(input_str):
    lines = input_str.strip().split('\n')
    grid = [[int(x) for x in line.split()] for line in lines]

    n, m = len(grid), len(grid[0])

    # For each 2, do a BFS outward through 3s
    # Track "direction of entry" into the 3-component from that 2

    cells_by_2_side = {}  # (cell_r, cell_c) -> list of (2_pos, entry_direction_from_cell)

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                q = collections.deque([(r, c)])
                seen_around_2 = set()  # (3-cell, direction_from_2)

                while q:
                    rr, cc = q.popleft()
                    if grid[rr][cc] == 3:
                        # Record this cell as being on a specific "side" of this 2
                        side_key = (rr, cc, 0)  # Will use distance instead

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < n and 0 <= nc < m:
                            if grid[nr][nc] == 3:
                                if (nr, nc) not in seen_around_2:
                                    seen_around_2.add((nr, nc))
                                    q.append((nr, nc))
                            elif grid[nr][nc] == 0:
                                pass  # Stop here, don't go through 0

    # Better approach: For each 2, label all reachable 3s by direction
    # Then count how many directions lead to each cell

    cells_with_multi_direction = {}

    for r in range(n):
        for c in range(m):
            if grid[r][c] == 2:
                directions_seen = collections.Counter()
                q = collections.deque([(r, c)])
                visited_for_this_2 = {(r, c)}

                while q:
                    rr, cc = q.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < n and 0 <= nc < m:
                            val = grid[nr][nc]
                            if val == 3 and (nr, nc) not in visited_for_this_2:
                                # Cell (nr, nc) can be reached from 2 via direction (-dr, -dc)
                                directions_seen[(nr, nc)] += 1
                                visited_for_this_2.add((nr, nc))
                                q.append((nr, nc))
                            elif val == 0:
                                pass

                    # Also mark boundary cells
                    if (rr, cc) in visited_for_this_2:
                        for ddir in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nrr, ncc = rr-ddir[0], cc-ddir[1]
                            if 0 <= nrr < n and 0 <= ncc < m and grid[nrr][ncc] == 2:
                                # Check if this is a new direction from this 2
                                pass

                print(f"2 at ({r},{c}): cells reached with multi-direction:")
                multi_dir_cells = {k:v for k,v in directions_seen.items() if v > 1}
                print(f"   Count={len(multi_dir_cells)}, {multi_dir_cells}")

    return cells_with_multi_direction

