# Based on analysis, implementing a solution using the rule:
# A 3 becomes 1 if:
# 1. It's adjacent horizontally to a 2 (left or right), OR
# 2. It can reach a 2 through a 3-path AND the "reach" is constrained
# 3. Or, it forms part of a "closed enclosure" with 2s

import collections

def solve_demo2(input_grid):
    n, m = len(input_grid), len(input_grid[0])
    result = [row[:] for row in input_grid]

    visited = set()
    q = collections.deque()

    # Find all edge 0s and 2s
    for r in range(n):
        for c in [0, m-1]:
            if input_grid[r][c] in (0, 2):
                q.append((r,c))
                visited.add((r,c))
    for c in range(m):
        for r in [0, n-1]:
            if input_grid[r][c] in (0, 2):
                q.append((r,c))
                visited.add((r,c))

    # Flood fill from edges through non-3 cells
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m and (nr,nc) not in visited:
                val = input_grid[nr][nc]
                if val in (0, 2):
                    visited.add((nr, nc))
                    q.append((nr, nc))

    # Now flood fill from ALL 2s separately
    q2 = collections.deque()
    for r in range(n):
        for c in range(m):
            if input_grid[r][c] == 2:
                q2.append((r,c))

    # For each 3-cell, track direction to nearest 2
    # Then mark as 1 if it can reach 2s in both vertical directions (up/down)
    # OR in both horizontal directions (left/right)
    # OR it's in an "L-corner" formed by 2s

    for r in range(n):
        for c in range(m):
            if input_grid[r][c] == 3:
                # BFS from this cell to find all reachable 2s
                reachable_2s = []
                seen = {(r,c)}
                queue = [(r,c)]

                while queue:
                    cr, cc = queue.pop(0)
                    val = input_grid[cr][cc]

                    for ddr, dcc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+ddr, cc+dcc
                        if 0 <= nr < n and 0 <= nc < m:
                            if (nr,nc) not in seen:
                                if input_grid[nr][nc] == 3:
                                    seen.add((nr,nc))
                                    queue.append((nr,nc))
                                elif input_grid[nr][nc] == 2:
                                    reachable_2s.append((nr,nc))

                # Check if reachable 2s span both vertical OR both horizontal
                has_up_or_down = False
                has_left_or_right = False

                for tr, tc in reachable_2s:
                    if tr > r:
                        has_up_or_down = True
                    elif tr < r:
                        has_up_or_down = True
                    if tc > c:
                        has_left_or_right = True
                    elif tc < c:
                        has_left_or_right = True

                # Mark as 1 if in BOTH directions or if adjacent horizontally to 2
                if has_up_or_down and has_left_or_right:
                    result[r][c] = 1
                elif c > 0 and input_grid[r][c-1] == 2:
                    result[r][c] = 1
                elif c < m-1 and input_grid[r][c+1] == 2:
                    result[r][c] = 1

    return result

