def min_dist_to_2(grid, r, c):
    n_rows, n_cols = len(grid), len(grid[0])
    min_d = float('inf')
    two_positions = []

    for dr in [-2,-1,0,1,2]:
        for dc in [-2,-1,0,1,2]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < n_rows and 0 <= nc < n_cols:
                dist = abs(dr) + abs(dc)
                if grid[nr][nc] == 2:
                    min_d = min(min_d, dist)
                    two_positions.append((nr, nc))

    return min_d, two_positions

