# Hypothesis: For each 3-cell, check which directions it lies relative to its nearest 2
def get_direction_relative_to_2(grid, r, c):
    """Get all directions (up, down, left, right, diagonals) to nearest 2"""
    min_d = float('inf')
    direction_patterns = []

    for dr in [-2,-1,0,1,2]:
        for dc in [-2,-1,0,1,2]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                dist = abs(dr) + abs(dc)
                if grid[nr][nc] == 2:
                    if dist <= min_d:
                        min_d = dist
                        rel_r, rel_c = dr, dc
                        # Determine direction category
                        if rel_r < 0:
                            dir_cat = "UP"
                        elif rel_r > 0:
                            dir_cat = "DOWN"
                        else:
                            dir_cat = "LEFT_RIGHT"

                        if rel_c < 0:
                            dir_cat += "-L"
                        elif rel_c > 0:
                            dir_cat += "-R"

                        # Also track which exact cells are the 2s nearby
                        actual_2s = []
                        for ndr in [-1,0,1]:
                            for ndc in [-1,0,1]:
                                if ndr==0 and ndc==0:
                                    continue
                                if grid[r+ndr][c+ndc] == 2:
                                    actual_2s.append((r+ndr, c+ndc))

                        direction_patterns.append({
                            'dist': dist,
                            'rel_pos': (rel_r, rel_c),
                            'dir_cat': dir_cat,
                            'actual_2s': actual_2s
                        })

    return min_d, direction_patterns

